function parseCsv(text){text=text.replace(/^\ufeff/,'');let rows=[],row=[],cell='',quote=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){cell+='"';i++}else quote=!quote}else if(c===','&&!quote){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(Boolean))rows.push(row);row=[];cell=''}else cell+=c}if(quote)throw Error('Unclosed quoted cell');row.push(cell);if(row.some(Boolean))rows.push(row);return rows}
function openCsvImport(key){openModal('Import Excel / CSV',`<div class="formbody importHelp"><div class="notice">Save your spreadsheet as CSV (UTF-8) in Excel, then select it here. Native .xlsx files are not supported by this prototype.</div><p>Use columns matching this module’s field names. Required fields are checked before import. Existing IDs are preserved and will not be overwritten.</p><input type="file" id="csvImportFile" accept=".csv,text/csv"><div id="csvImportPreview" style="margin-top:16px"></div></div><div class="formactions">${btn('Cancel','cancel','secondary')}<button class="btn" id="confirmCsvImport" disabled>Import Records</button></div>`);let records=[];$('#csvImportFile').onchange=async e=>{try{let file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024)throw Error('File must be under 5 MB');let rows=parseCsv(await file.text());if(rows.length<2)throw Error('Include column headers and at least one record');let normalize=x=>x.toLowerCase().replace(/[^a-z0-9]/g,'');let fields=schemas[key].filter(f=>f.key),headers=rows.shift().map(normalize),aliases={customername:'name',staffname:'name',servicename:'name',partname:'name',vehiclenumber:'number',mobilenumber:'mobile',alternatemobile:'alt',emailid:'email',customertype:'type',customerid:'id',staffid:'id',serviceid:'id',vehicleid:'id',partcodesku:'id',standardlabourcharge:'charge',purchaseprice:'purchase',sellingprice:'price',openingstock:'opening',minstockalert:'min',rackno:'rack',fueltype:'fuel',vehicletype:'type',vehiclebrand:'brand',vehiclemake:'vehicleMake',vehiclemodel:'model'};let fieldMap=headers.map(h=>aliases[h]||fields.find(f=>normalize(f.label)===h||normalize(f.key)===h)?.key||'');records=rows.slice(0,1000).map(row=>{let r={};fieldMap.forEach((k,i)=>{if(k){if(key==='parts'&&headers[i]==='vehiclemake')k='vehicleMake';if(key==='parts'&&headers[i]==='vehiclemodel')k='vehicleModel';r[k]=row[i]?.trim()||''}});for(let f of fields){if(r[f.key]===undefined)r[f.key]=f.default??'';if(f.type==='number')r[f.key]=Number(r[f.key]||0);if(f.required&&!String(r[f.key]).trim()&&f.key!=='id')throw Error('Missing required '+f.label)}return r});if(records.some(r=>r.id&&db[key].some(x=>x.id===r.id)))throw Error('A supplied ID already exists; existing records will not be overwritten');let ids=records.map(r=>r.id).filter(Boolean);if(new Set(ids).size!==ids.length)throw Error('Duplicate IDs in file');$('#csvImportPreview').innerHTML=`<div class="notice">Ready to import ${records.length} records.</div>`;$('#confirmCsvImport').disabled=false}catch(err){$('#csvImportPreview').textContent='Import rejected: '+err.message;$('#confirmCsvImport').disabled=true;records=[]}};$('#confirmCsvImport').onclick=()=>{for(let r of records){if(!r.id)r.id=nextId(key);db[key].push(r)}audit('Import',`${records.length} ${key} records imported from CSV`);save('CSV records imported');closeModal();render()}}
const originalRenderFidelity=render;
render=function(){let scroll=$('#navigation')?.scrollTop||0;document.body.dataset.view=page;originalRenderFidelity();$('#navigation').scrollTop=scroll;for(let b of $$('#content .rowactions [data-edit]'))b.classList.add('editButton');for(let b of $$('#content .rowactions [data-delete]'))b.classList.add('deleteButton');for(let b of $$('#content .rowactions [data-invoice]'))b.classList.add('printButton');for(let select of $$('#content .filters select'))if(select.options.length>8)makeSearchSelect(select);if(page==='dashboard'){let statIcons=$$('.statlabel');if(statIcons[3])statIcons[3].innerHTML=icon('rupee')+'REVENUE';let watermark=$$('.stat .watermark');if(watermark[3])watermark[3].innerHTML=icon('rupee')} };
const renderWithSharedStyles=render;
render=function(){renderWithSharedStyles();if(page==='jobs'){for(let [id,assign]of [['jobCustomerFilter',v=>jobCustomerFilter=v],['jobWorkFilter',v=>jobWorkFilter=v],['jobDateFrom',v=>jobDateFrom=v],['jobDateTo',v=>jobDateTo=v]]){let element=$('#'+id);if(element)element.addEventListener('change',e=>{assign(e.target.value);render()})}if($('#resetJobFilters'))$('#resetJobFilters').onclick=()=>{jobCustomerFilter='';jobWorkFilter='';jobDateFrom='';jobDateTo='';search='';filter='';render()};for(let id of ['jobCustomerFilter'])makeSearchSelect($('#'+id));}};
render();
function closeHeaderPanel(){$('#headerPanel')?.remove()}
function headerPanel(type){closeHeaderPanel();let panel=document.createElement('section');panel.id='headerPanel';panel.className='headerPanel';panel.setAttribute('role','dialog');panel.setAttribute('aria-label',type==='profile'?'User Profile & Access':'Pending Jobs Notifications');if(type==='profile'){let modules=groups.flatMap(g=>g[1]).filter(m=>m[0]!=='payroll');panel.innerHTML=`<div class="accessHead"><div class="accessTitle">${icon('shield')}USER PROFILE & ACCESS<button type="button" data-closepanel aria-label="Close profile">×</button></div><div class="accessPerson"><span class="avatar">A</span><div><strong>admin</strong><p><b>ADMIN</b> admin</p></div></div></div><div class="accessSummary"><small>MODULE PERMISSIONS</small><strong>✓ All ${modules.length} Prototype Modules Accessible</strong><div class="accessTabs"><button type="button" class="selected">All (${modules.length})</button><button type="button">Accessible (${modules.length})</button><button type="button" id="restrictedAccessTab">Restricted (0)</button></div></div><div class="accessSearch"><input id="accessSearch" type="search" placeholder="Search modules..." aria-label="Search modules"></div><div class="accessModules">${modules.map(([key,title,i])=>`<button type="button" class="accessModule" data-page="${key}" data-modulename="${esc(title.toLowerCase())}"><span class="accessIcon">${icon(i)}</span><strong>${esc(title)}</strong><span class="accessBadge">✓ Full Access</span></button>`).join('')}</div><div class="accessFooter"><button type="button" class="btn secondary small" data-page="users">User Management</button><span>Prototype access preview</span></div>`;document.body.appendChild(panel);let filterModules=()=>{let q=$('#accessSearch').value.toLowerCase();for(let item of $$('#headerPanel .accessModule'))item.hidden=!item.dataset.modulename.includes(q)};$('#accessSearch').oninput=filterModules;for(let b of $$('#headerPanel .accessTabs button'))b.onclick=()=>{for(let tab of $$('#headerPanel .accessTabs button'))tab.classList.toggle('selected',tab===b);if(b.id==='restrictedAccessTab')for(let item of $$('#headerPanel .accessModule'))item.hidden=true;else filterModules()}}else{let jobs=db.jobs.filter(j=>!['Completed','Delivered','Cancelled'].includes(j.status));panel.classList.add('notificationPanel');panel.innerHTML=`<div class="accessHead"><div class="accessTitle">${icon('bell')}PENDING JOBS (${jobs.length})<button type="button" data-closepanel aria-label="Close notifications">×</button></div></div><div class="accessModules">${jobs.length?jobs.map(j=>`<button type="button" class="notificationJob" data-page="jobs"><strong>${esc(j.id)}</strong><span>${esc(name('customers',j.customer))}</span><small>${esc(number(j.bike))}</small>${badge(j.status)}</button>`).join(''):'<p class="empty">No pending jobs</p>'}</div><div class="accessFooter"><button type="button" class="btn secondary small" data-page="jobs">View in Job Cards →</button></div>`;document.body.appendChild(panel)}panel.querySelector('[data-closepanel]').onclick=closeHeaderPanel;panel.querySelector('[data-closepanel]').focus()}
$('#profile').onclick=()=>$('#headerPanel')?closeHeaderPanel():headerPanel('profile');
$('#notifications').onclick=()=>$('#headerPanel')?closeHeaderPanel():headerPanel('notifications');
document.addEventListener('click',e=>{if($('#headerPanel')&&!e.target.closest('#headerPanel,#profile,#notifications'))closeHeaderPanel();if(e.target.closest('#headerPanel [data-page]'))closeHeaderPanel()},true);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#headerPanel')){closeHeaderPanel();$('#profile').focus()}},true);


